requireLogin();
if (getUserRole() !== 'admin') { header('Location: ../login.php'); exit; }
$db = getDBConnection();
$familyAccessReady = $db && familyAccessEnsureSchema($db);
$userId = (int)getUserId();
$sessions = termResultsSessionRows($db);
$message = '';

function eyUpload(string $field, string $prefix): ?string {
    $file = $_FILES[$field] ?? null;
    if (!$file || $file['error'] === UPLOAD_ERR_NO_FILE) return null;
    if ($file['error'] !== UPLOAD_ERR_OK || $file['size'] > 5 * 1024 * 1024) throw new RuntimeException('Image must upload successfully and be no larger than 5 MB.');
    $info = @getimagesize($file['tmp_name']);
    $ext = ['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$info['mime'] ?? ''] ?? null;
    if (!$ext) throw new RuntimeException('Upload a JPG, PNG, or WebP image.');
    $dir = dirname(__DIR__) . '/uploads/early_years';
    if (!is_dir($dir) && !mkdir($dir, 0755, true) && !is_dir($dir)) throw new RuntimeException('Could not create the upload folder.');
    $name = $prefix . '_' . bin2hex(random_bytes(12)) . '.' . $ext;
    if (!move_uploaded_file($file['tmp_name'], $dir . '/' . $name)) throw new RuntimeException('Could not save the uploaded image.');
    return 'uploads/early_years/' . $name;
}
function eyUploadRow(string $field, int $index, string $prefix): ?string {
    if (!isset($_FILES[$field]['error'][$index]) || $_FILES[$field]['error'][$index] === UPLOAD_ERR_NO_FILE) return null;
    $file = [
        'name' => $_FILES[$field]['name'][$index] ?? '',
        'type' => $_FILES[$field]['type'][$index] ?? '',
        'tmp_name' => $_FILES[$field]['tmp_name'][$index] ?? '',
        'error' => $_FILES[$field]['error'][$index],
        'size' => $_FILES[$field]['size'][$index] ?? 0,
    ];
    $single = $_FILES[$field] ?? null;
    $_FILES[$field] = $file;
    try { return eyUpload($field, $prefix); }
    finally { if ($single === null) unset($_FILES[$field]); else $_FILES[$field] = $single; }
}
function eyAssignTeachers(mysqli $db, int $classId, array $teacherIds): void {
    $teacherIds = array_values(array_unique(array_filter(array_map('intval', $teacherIds))));
    $delete = $db->prepare('DELETE FROM early_years_class_teachers WHERE class_id=?');
    $delete->bind_param('i', $classId); $delete->execute(); $delete->close();
    $stmt = $db->prepare('INSERT INTO early_years_class_teachers(class_id,teacher_id) SELECT ?,id FROM users WHERE id=? AND role IN (\'teacher\',\'admin_teacher\',\'admin\')');
    foreach ($teacherIds as $teacherId) { $stmt->bind_param('ii', $classId, $teacherId); $stmt->execute(); }
    $stmt->close();
}

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (!termResultsVerifyCsrf($_POST['csrf_token'] ?? '')) $message = 'Session expired. Refresh and try again.';
    else try {
        $action = $_POST['action'] ?? '';
        if ($action === 'class' || $action === 'edit_class') {
            $name = trim($_POST['name'] ?? ''); $teacherIds = $_POST['teacher_ids'] ?? [];
            if ($name === '') throw new RuntimeException('Enter a class name.');
            $signature = eyUpload('teacher_signature', 'signature');
            if ($action === 'class') {
                $stmt = $db->prepare('INSERT INTO early_years_classes(name,teacher_id,teacher_signature_path) VALUES(?,NULL,?)');
                $stmt->bind_param('ss', $name, $signature); $stmt->execute(); $classId = (int)$db->insert_id; $stmt->close();
            } else {
                $classId = (int)($_POST['class_id'] ?? 0); if (!$classId) throw new RuntimeException('Choose a valid class.');
                if ($signature) { $stmt=$db->prepare('UPDATE early_years_classes SET name=?,teacher_signature_path=? WHERE id=?'); $stmt->bind_param('ssi',$name,$signature,$classId); }
                else { $stmt=$db->prepare('UPDATE early_years_classes SET name=? WHERE id=?'); $stmt->bind_param('si',$name,$classId); }
                $stmt->execute(); $stmt->close();
            }
            eyAssignTeachers($db, $classId, is_array($teacherIds) ? $teacherIds : []);
            $message = $action === 'class' ? 'Early Years class saved.' : 'Early Years class and teacher assignments updated.';
        } elseif ($action === 'family_code') {
            $label = trim($_POST['family_label'] ?? '');
            $nextNumber = (int)($db->query("SELECT COALESCE(MAX(CAST(SUBSTRING_INDEX(access_code,'-',-1) AS UNSIGNED)),0)+1 AS n FROM early_years_family_codes WHERE access_code LIKE 'FAMAIIS-EY-%'")->fetch_assoc()['n'] ?? 1);
            $code = 'FAMAIIS-EY-' . str_pad((string)$nextNumber, 6, '0', STR_PAD_LEFT);
            $stmt = $db->prepare('INSERT INTO early_years_family_codes(access_code,family_label,created_by) VALUES(?,?,?)');
            $stmt->bind_param('ssi',$code,$label,$userId); $stmt->execute(); $stmt->close(); $message = 'Family code created: ' . $code;
        } elseif ($action === 'edit_family_code') {
            $id = (int)($_POST['family_id'] ?? 0); $label = trim($_POST['family_label'] ?? '');
            if ($label === '') throw new RuntimeException('Enter a family name.');
            $code = strtoupper(trim($_POST['access_code'] ?? ''));
            if (!$id || !preg_match('/^FAMAIIS(-EY)?-[0-9]+$/', $code)) throw new RuntimeException('Use the format FAMAIIS-number or FAMAIIS-EY-number for the family code.');
            $stmt = $db->prepare('UPDATE early_years_family_codes SET access_code=?,family_label=? WHERE id=?');
            $stmt->bind_param('ssi',$code,$label,$id); $stmt->execute(); $stmt->close(); $message = 'Family code updated.';
        } elseif ($action === 'delete_family_code') {
            $id = (int)($_POST['family_id'] ?? 0);
            if (!$id) throw new RuntimeException('Choose a valid family code.');
            $stmt = $db->prepare('DELETE FROM early_years_family_codes WHERE id=?');
            $stmt->bind_param('i',$id); $stmt->execute(); $stmt->close(); $message = 'Family code deleted. Pupils and reports remain in the school records.';
        } elseif ($action === 'term_setting') {
            $sessionId=(int)($_POST['session_id']??0); $term=(int)($_POST['term']??0); $next=trim($_POST['next_term_begins']??'') ?: null;
            if (!$sessionId || $term<1 || $term>3 || ($next && !preg_match('/^\d{4}-\d{2}-\d{2}$/',$next))) throw new RuntimeException('Choose a valid session, term, and next-term date.');
            $stmt=$db->prepare('INSERT INTO early_years_term_settings(session_id,term,next_term_begins,updated_by) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE next_term_begins=VALUES(next_term_begins),updated_by=VALUES(updated_by)');
            $stmt->bind_param('iisi',$sessionId,$term,$next,$userId); $stmt->execute(); $stmt->close(); $message='Next term date saved.';
        } elseif ($action === 'school_settings') {
            $headId=(int)($_POST['head_user_id']??0); $stmt=$db->prepare('SELECT full_name FROM users WHERE id=?'); $stmt->bind_param('i',$headId); $stmt->execute(); $headName=(string)($stmt->get_result()->fetch_assoc()['full_name']??''); $stmt->close();
            if (!$headId || !$headName) throw new RuntimeException('Select an existing CBT user as Head of School.');
            $signature=eyUpload('head_signature','signature');
            $stmt=$db->prepare('INSERT INTO early_years_school_settings(id,head_user_id,head_name,head_signature_path,updated_by) VALUES(1,?,?,?,?) ON DUPLICATE KEY UPDATE head_user_id=VALUES(head_user_id),head_name=VALUES(head_name),head_signature_path=COALESCE(VALUES(head_signature_path),head_signature_path),updated_by=VALUES(updated_by)');
            $stmt->bind_param('issi',$headId,$headName,$signature,$userId); $stmt->execute(); $stmt->close(); $message='Head of School details saved.';
        } elseif ($action === 'bulk_students') {
            $classId=(int)($_POST['class_id']??0); $familyId=(int)($_POST['family_id']??0);
            $names=$_POST['full_name']??[]; $admissions=$_POST['admission_number']??[]; $dates=$_POST['date_of_birth']??[]; $genders=$_POST['gender']??[];
            if (!$classId || !is_array($names)) throw new RuntimeException('Choose a class and enter at least one pupil name.');
            $rows=[];
            foreach ($names as $i=>$rawName) {
                $name=trim((string)$rawName); $admission=trim((string)($admissions[$i]??'')); $dob=trim((string)($dates[$i]??'')) ?: null; $gender=trim((string)($genders[$i]??''));
                $gender=$gender==='M'?'Male':($gender==='F'?'Female':$gender);
                if ($name==='') { if ($admission!=='' || $dob || $gender!=='') throw new RuntimeException('Enter a name for every pupil row that has other details.'); continue; }
                $rows[]=[$i,$name,$admission,$dob,$gender];
            }
            if (!$rows) throw new RuntimeException('Enter at least one pupil name.');
            $db->begin_transaction();
            try {
                $insert=$db->prepare('INSERT INTO early_years_students(class_id,full_name,admission_number,date_of_birth,gender,passport_path) VALUES(?,?,?,?,?,?)');
                $linkEy=$familyId?$db->prepare('INSERT IGNORE INTO early_years_family_students(family_id,student_id) VALUES(?,?)'):null;
                $linkFamily=$familyId?$db->prepare("INSERT IGNORE INTO family_student_links(family_id,student_type,student_id) VALUES(?,'early_years',?)"):null;
                foreach($rows as [$rowIndex,$name,$admission,$dob,$gender]) {
                    $photo=eyUploadRow('pupil_photo',$rowIndex,'pupil');
                    $insert->bind_param('isssss',$classId,$name,$admission,$dob,$gender,$photo); $insert->execute(); $studentId=(int)$db->insert_id;
                    if($familyId){$linkEy->bind_param('ii',$familyId,$studentId);$linkEy->execute();$linkFamily->bind_param('ii',$familyId,$studentId);$linkFamily->execute();}
                }
                $insert->close(); if($linkEy)$linkEy->close(); if($linkFamily)$linkFamily->close();
                $db->commit(); $message=count($rows).' pupils registered successfully.';
            } catch(Throwable $e) { $db->rollback(); throw $e; }
        } elseif ($action === 'bulk_edit_students') {
            $classId=(int)($_POST['class_id']??0); $ids=$_POST['student_ids']??[]; $names=$_POST['full_names']??[]; $admissions=$_POST['admission_numbers']??[]; $dates=$_POST['date_of_births']??[]; $genders=$_POST['genders']??[]; $familyIds=$_POST['family_ids']??[];
            if(!$classId || !is_array($ids) || !$ids) throw new RuntimeException('Choose a class with pupils to edit.');
            $valid=[]; $check=$db->prepare('SELECT id FROM early_years_students WHERE class_id=?'); $check->bind_param('i',$classId); $check->execute(); $checkResult=$check->get_result(); while($row=$checkResult->fetch_assoc())$valid[(int)$row['id']]=true; $check->close();
            $db->begin_transaction();
            try {
                $update=$db->prepare('UPDATE early_years_students SET full_name=?,admission_number=?,date_of_birth=?,gender=? WHERE id=? AND class_id=?');
                $deleteEy=$db->prepare('DELETE FROM early_years_family_students WHERE student_id=?');
                $deleteLinks=$db->prepare("DELETE FROM family_student_links WHERE student_type='early_years' AND student_id=?");
                $insertEy=$db->prepare('INSERT IGNORE INTO early_years_family_students(family_id,student_id) VALUES(?,?)');
                $insertLinks=$db->prepare("INSERT IGNORE INTO family_student_links(family_id,student_type,student_id) VALUES(?,'early_years',?)");
                foreach($ids as $i=>$rawId) {
                    $studentId=(int)$rawId; if(!$studentId || empty($valid[$studentId])) throw new RuntimeException('One or more pupils are no longer in the selected class. Refresh and try again.');
                    $name=trim((string)($names[$i]??'')); if($name==='') throw new RuntimeException('Pupil names cannot be blank.');
                    $admission=trim((string)($admissions[$i]??'')); $dob=trim((string)($dates[$i]??''))?:null; $gender=trim((string)($genders[$i]??'')); $familyId=(int)($familyIds[$i]??0);
                    if($gender==='M')$gender='Male';elseif($gender==='F')$gender='Female';
                    $update->bind_param('ssssii',$name,$admission,$dob,$gender,$studentId,$classId); $update->execute();
                    $deleteEy->bind_param('i',$studentId);$deleteEy->execute();$deleteLinks->bind_param('i',$studentId);$deleteLinks->execute();
                    if($familyId){$insertEy->bind_param('ii',$familyId,$studentId);$insertEy->execute();$insertLinks->bind_param('ii',$familyId,$studentId);$insertLinks->execute();}
                }
                $update->close();$deleteEy->close();$deleteLinks->close();$insertEy->close();$insertLinks->close();$db->commit();$message=count($ids).' pupils updated.';
            } catch(Throwable $e) { $db->rollback(); throw $e; }
        } elseif ($action === 'student' || $action === 'edit_student') {
            $classId=(int)($_POST['class_id']??0); $name=trim($_POST['full_name']??''); $admission=trim($_POST['admission_number']??''); $dob=trim($_POST['date_of_birth']??'') ?: null; $gender=trim($_POST['gender']??''); $familyId=(int)($_POST['family_id']??0);
            if (!$classId || !$name) throw new RuntimeException('Choose a class and enter the pupil name.');
            $photo=eyUpload('pupil_photo','pupil');
            if ($action === 'student') {
                $stmt=$db->prepare('INSERT INTO early_years_students(class_id,full_name,admission_number,date_of_birth,gender,passport_path) VALUES(?,?,?,?,?,?)');
                $stmt->bind_param('isssss',$classId,$name,$admission,$dob,$gender,$photo); $stmt->execute(); $studentId=(int)$db->insert_id; $stmt->close();
            } else {
                $studentId=(int)($_POST['student_id']??0); if (!$studentId) throw new RuntimeException('Choose a valid pupil.');
                if ($photo) { $stmt=$db->prepare('UPDATE early_years_students SET class_id=?,full_name=?,admission_number=?,date_of_birth=?,gender=?,passport_path=? WHERE id=?'); $stmt->bind_param('isssssi',$classId,$name,$admission,$dob,$gender,$photo,$studentId); }
                else { $stmt=$db->prepare('UPDATE early_years_students SET class_id=?,full_name=?,admission_number=?,date_of_birth=?,gender=? WHERE id=?'); $stmt->bind_param('issssi',$classId,$name,$admission,$dob,$gender,$studentId); }
                $stmt->execute(); $stmt->close();
                $stmt=$db->prepare('DELETE FROM early_years_family_students WHERE student_id=?'); $stmt->bind_param('i',$studentId); $stmt->execute(); $stmt->close();
                $stmt=$db->prepare("DELETE FROM family_student_links WHERE student_type='early_years' AND student_id=?"); $stmt->bind_param('i',$studentId); $stmt->execute(); $stmt->close();
            }
            if ($familyId) { $stmt=$db->prepare('INSERT IGNORE INTO early_years_family_students(family_id,student_id) VALUES(?,?)'); $stmt->bind_param('ii',$familyId,$studentId); $stmt->execute(); $stmt->close(); $stmt=$db->prepare("INSERT IGNORE INTO family_student_links(family_id,student_type,student_id) VALUES(?,'early_years',?)"); $stmt->bind_param('ii',$familyId,$studentId); $stmt->execute(); $stmt->close(); }
            $message=$action==='student'?'Pupil registered.':'Pupil details updated.';
        } elseif ($action === 'delete_student') {
            $studentId=(int)($_POST['student_id']??0); $stmt=$db->prepare('DELETE FROM early_years_students WHERE id=?'); $stmt->bind_param('i',$studentId); $stmt->execute(); $stmt->close(); $message='Pupil and Early Years reports deleted.';
        }
    } catch (Throwable $e) { $message=$e instanceof mysqli_sql_exception ? 'Could not save. Check for duplicate class names or family assignments.' : $e->getMessage(); }
}

$schoolSettings=$db->query('SELECT head_user_id,head_name,head_signature_path FROM early_years_school_settings WHERE id=1')->fetch_assoc() ?: ['head_user_id'=>0,'head_name'=>'','head_signature_path'=>''];
$headUsers=$db->query('SELECT id,full_name,role FROM users ORDER BY full_name')->fetch_all(MYSQLI_ASSOC);
$teachers=$db->query("SELECT id,full_name,role FROM users WHERE role IN ('teacher','admin_teacher','admin') ORDER BY full_name")->fetch_all(MYSQLI_ASSOC);
$classes=$db->query('SELECT c.id,c.name,c.teacher_signature_path,(SELECT COUNT(*) FROM early_years_students s WHERE s.class_id=c.id) student_count FROM early_years_classes c ORDER BY c.name')->fetch_all(MYSQLI_ASSOC);
$classTeachers=[]; $rs=$db->query('SELECT class_id,teacher_id FROM early_years_class_teachers'); while($r=$rs->fetch_assoc()) $classTeachers[(int)$r['class_id']][]=(int)$r['teacher_id'];
$familyCodes=$db->query('SELECT fc.id,fc.access_code,fc.family_label,(SELECT COUNT(*) FROM early_years_family_students fs WHERE fs.family_id=fc.id) pupil_count FROM early_years_family_codes fc ORDER BY fc.id DESC')->fetch_all(MYSQLI_ASSOC);
$students=$db->query('SELECT s.*,c.name class_name,(SELECT fs.family_id FROM early_years_family_students fs WHERE fs.student_id=s.id LIMIT 1) family_id FROM early_years_students s JOIN early_years_classes c ON c.id=s.class_id ORDER BY c.name,s.full_name')->fetch_all(MYSQLI_ASSOC);
$pupilListClassId=(int)($_GET['pupil_list_class_id']??0); $listedStudents=$pupilListClassId?array_values(array_filter($students,static fn($pupil)=>(int)$pupil['class_id']===$pupilListClassId)):$students;
$bulkEditClassId=(int)($_POST['class_id']??$_GET['bulk_edit_class_id']??0); $classStudents=array_values(array_filter($students,static fn($student)=>(int)$student['class_id']===$bulkEditClassId));
$selectedSession=(int)($_REQUEST['session_id']??0); if(!$selectedSession) foreach($sessions as $x) if((int)$x['is_current']) {$selectedSession=(int)$x['id'];break;} if(!$selectedSession&&$sessions)$selectedSession=(int)$sessions[0]['id'];
$selectedTerm=max(1,min(3,(int)($_REQUEST['term']??1))); $action = (string)($_POST['action'] ?? ''); $activeTab = match ($action) { 'family_code','edit_family_code','delete_family_code' => 'family', 'class','edit_class' => 'class_create', 'student','bulk_students' => 'pupil_add', 'edit_student','delete_student' => 'pupil_list', 'bulk_edit_students' => 'bulk_edit', 'term_setting','school_settings' => 'settings', default => (($_GET['tab']??'')==='bulk_edit'?'bulk_edit':(($_GET['tab']??'')==='pupil_list'?'pupil_list':'family')) }; $nextTerm=''; if($selectedSession){$stmt=$db->prepare('SELECT next_term_begins FROM early_years_term_settings WHERE session_id=? AND term=?');$stmt->bind_param('ii',$selectedSession,$selectedTerm);$stmt->execute();$nextTerm=$stmt->get_result()->fetch_assoc()['next_term_begins']??'';$stmt->close();}
include '../includes/header.php';
