</section></div><div class="tab-pane fade ey-admin-panel <?=$activeTab==='bulk_edit'?'show active':''?>" id="ey-tab-bulk-edit" role="tabpanel"><section><h2 class="h5">Edit pupils by class</h2><form method="get" class="row g-2 align-items-end mb-3"><input type="hidden" name="tab" value="bulk_edit"><div class="col-md-5"><label class="form-label">Choose a class to edit multiple pupils</label><select class="form-select" name="bulk_edit_class_id"><option value="0">Select class</option><?php foreach($classes as $c):?><option value="<?=$c['id']?>" <?=$bulkEditClassId===(int)$c['id']?'selected':''?>><?=htmlspecialchars($c['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><button class="btn btn-outline-primary">Load class</button></div></form><?php if($bulkEditClassId):?><?php if($classStudents):?><form method="post" class="card card-body mb-4"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(termResultsCsrfToken())?>"><input type="hidden" name="action" value="bulk_edit_students"><input type="hidden" name="class_id" value="<?=$bulkEditClassId?>"><h3 class="h6">Edit pupils in <?=htmlspecialchars($classStudents[0]['class_name'])?></h3><div class="table-responsive"><table class="table table-sm table-bordered align-middle"><thead><tr><th>Name</th><th>Admission number</th><th>Date of birth</th><th>Gender</th><th>Family code</th></tr></thead><tbody><?php foreach($classStudents as $pupil):?><tr><td><input type="hidden" name="student_ids[]" value="<?=$pupil['id']?>"><input class="form-control" name="full_names[]" value="<?=htmlspecialchars($pupil['full_name'])?>" required></td><td><input class="form-control" name="admission_numbers[]" value="<?=htmlspecialchars($pupil['admission_number']??'')?>"></td><td><input class="form-control" type="date" name="date_of_births[]" value="<?=htmlspecialchars($pupil['date_of_birth']??'')?>"></td><td><select class="form-select" name="genders[]"><option value="">—</option><option value="Male" <?=$pupil['gender']==='Male'||$pupil['gender']==='M'?'selected':''?>>M · Male</option><option value="Female" <?=$pupil['gender']==='Female'||$pupil['gender']==='F'?'selected':''?>>F · Female</option></select></td><td><select class="form-select" name="family_ids[]"><option value="0">No family code</option><?php foreach($familyCodes as $fc):?><option value="<?=$fc['id']?>" <?=$pupil['family_id']==$fc['id']?'selected':''?>><?=htmlspecialchars(($fc['family_label']?:'Family').' · '.$fc['access_code'])?></option><?php endforeach;?></select></td></tr><?php endforeach;?></tbody></table></div><div class="text-end"><button class="btn btn-primary">Save all pupil changes</button></div></form><?php else:?><div class="alert alert-info">No pupils are registered in this class.</div><?php endif;?><?php endif;?></section></div><div class="tab-pane fade ey-admin-panel <?=$activeTab==='pupil_list'?'show active':''?>" id="ey-tab-pupil-list" role="tabpanel"><section class="ey-pupil-list"><div class="d-flex justify-content-between align-items-center flex-wrap gap-2 mb-3"><div><div class="small text-uppercase text-primary fw-bold">Student records</div><h2 class="h5 mb-0">Early Years pupils</h2></div><span class="badge rounded-pill bg-primary-subtle text-primary px-3 py-2"><?=count($listedStudents)?> pupils</span></div><form method="get" class="ey-pupil-filter card card-body mb-3"><input type="hidden" name="tab" value="pupil_list"><div class="row g-2 align-items-end"><div class="col-md-5"><label class="form-label mb-1" for="pupil-list-class">Filter by class</label><select class="form-select" id="pupil-list-class" name="pupil_list_class_id"><option value="0">All classes</option><?php foreach($classes as $c):?><option value="<?=$c['id']?>" <?=$pupilListClassId===(int)$c['id']?'selected':''?>><?=htmlspecialchars($c['name'])?></option><?php endforeach;?></select></div><div class="col-auto"><button class="btn btn-primary"><i class="fas fa-filter me-1"></i>Show pupils</button></div><?php if($pupilListClassId):?><div class="col-auto"><a class="btn btn-outline-secondary" href="early_years.php?tab=pupil_list">Clear filter</a></div><?php endif;?></div></form><div class="table-responsive ey-pupil-table-wrap"><table class="table table-hover align-middle mb-0 ey-pupil-table"><thead><tr><th>Photo</th><th>Pupil</th><th>Admission no.</th><th>Class</th><th>DOB</th><th></th></tr></thead><tbody><?php foreach($listedStudents as $s):?><tr><td><?php if($s['passport_path']):?><img src="../<?=htmlspecialchars($s['passport_path'])?>" alt="" style="width:52px;height:60px;object-fit:cover"><?php endif;?></td><td><?=htmlspecialchars($s['full_name'])?></td><td><?=htmlspecialchars($s['admission_number']??'')?></td><td><?=htmlspecialchars($s['class_name'])?></td><td><?=htmlspecialchars($s['date_of_birth']??'')?></td><td><details><summary class="btn btn-sm btn-outline-primary">Edit</summary><form method="post" enctype="multipart/form-data" class="ey-edit-form mt-2"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(termResultsCsrfToken())?>"><input type="hidden" name="action" value="edit_student"><input type="hidden" name="student_id" value="<?=$s['id']?>"><label class="form-label">Name</label><input class="form-control mb-2" name="full_name" value="<?=htmlspecialchars($s['full_name'])?>" required><label class="form-label">Class</label><select class="form-select mb-2" name="class_id"><?php foreach($classes as $c):?><option value="<?=$c['id']?>" <?=$s['class_id']==$c['id']?'selected':''?>><?=htmlspecialchars($c['name'])?></option><?php endforeach;?></select><label class="form-label">Admission number</label><input class="form-control mb-2" name="admission_number" value="<?=htmlspecialchars($s['admission_number']??'')?>"><label class="form-label">Date of birth</label><input class="form-control mb-2" type="date" name="date_of_birth" value="<?=htmlspecialchars($s['date_of_birth']??'')?>"><label class="form-label">Gender</label><input class="form-control mb-2" name="gender" value="<?=htmlspecialchars($s['gender']??'')?>"><label class="form-label">Family access code</label><select class="form-select mb-2" name="family_id"><option value="0">No family code</option><?php foreach($familyCodes as $fc):?><option value="<?=$fc['id']?>" <?=$s['family_id']==$fc['id']?'selected':''?>><?=htmlspecialchars(($fc['family_label']?:'Family').' · '.$fc['access_code'])?></option><?php endforeach;?></select><label class="form-label">Replace pupil photo (optional)</label><input class="form-control mb-2" type="file" name="pupil_photo" accept="image/jpeg,image/png,image/webp"><button class="btn btn-sm btn-primary">Save changes</button></form></details><form method="post" class="mt-1" onsubmit="return confirm('Delete this pupil and their reports?')"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(termResultsCsrfToken())?>"><input type="hidden" name="action" value="delete_student"><input type="hidden" name="student_id" value="<?=$s['id']?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></section>
</section></div></div></main><style>@media print{@page{size:A4 portrait;margin:14mm}body *{visibility:hidden!important}#ey-family-codes,#ey-family-codes *{visibility:visible!important}#ey-family-codes{position:absolute;inset:0;width:100%;border:0!important;box-shadow:none!important}#ey-family-codes .no-print{display:none!important}#ey-family-codes table{width:100%;font-size:12pt}#ey-family-codes td,#ey-family-codes th{padding:8px;border:1px solid #444!important}.ey-code{font-size:14pt!important}}</style><script>
const bulkStudentRows=document.getElementById('ey-bulk-student-rows');
let bulkStudentRowIndex=bulkStudentRows?.rows.length||0;
document.getElementById('ey-add-student-row')?.addEventListener('click',()=>{
 const row=bulkStudentRows.querySelector('tr').cloneNode(true);
 const rowIndex=bulkStudentRowIndex++;
 row.querySelectorAll('input').forEach(input=>{input.removeAttribute('required');if(input.type==='radio')input.checked=false;else input.value='';});
 row.querySelector('input[name="gender[]"]').value='';
 row.querySelectorAll('.ey-gender-choice').forEach(input=>{input.name=`gender-choice-${rowIndex}`;input.id=`ey-gender-${rowIndex}-${input.value.toLowerCase()}`;input.nextElementSibling.htmlFor=input.id;});
 const preview=row.querySelector('.ey-photo-preview');if(preview){preview.src='';preview.hidden=true;}
 bulkStudentRows.appendChild(row);
});
bulkStudentRows?.addEventListener('change',event=>{
 const choice=event.target.closest('.ey-gender-choice');if(choice){choice.closest('td').querySelector('input[name="gender[]"]').value=choice.value;return;}
 const input=event.target.closest('input[type=file][name="pupil_photo[]"]');if(!input)return;
 const preview=input.parentElement.querySelector('.ey-photo-preview');if(!preview)return;
 if(preview.dataset.objectUrl)URL.revokeObjectURL(preview.dataset.objectUrl);
 const file=input.files&&input.files[0];if(!file){preview.hidden=true;preview.removeAttribute('src');delete preview.dataset.objectUrl;return;}
 const objectUrl=URL.createObjectURL(file);preview.dataset.objectUrl=objectUrl;preview.src=objectUrl;preview.hidden=false;
});
bulkStudentRows?.addEventListener('click',event=>{
 const button=event.target.closest('.ey-remove-student-row');if(!button)return;
 if(bulkStudentRows.rows.length>1)button.closest('tr').remove();
 else button.closest('tr').querySelectorAll('input').forEach(input=>input.value='');
});
</script><?php include '../includes/footer.php';?>
